class Solution:
    def threeSum(self, nums: List[int]) -> List[List[int]]:
        a = sorted(nums); n = len(a); res = []
        for i in range(n - 2):
            if i and a[i] == a[i - 1]: continue
            l, r = i + 1, n - 1
            while l < r:
                s = a[i] + a[l] + a[r]
                if s < 0: l += 1
                elif s > 0: r -= 1
                else:
                    res.append([a[i], a[l], a[r]]); l += 1; r -= 1
                    while l < r and a[l] == a[l - 1]: l += 1
        return res

