function threeSum(nums) {
  const cnt = new Map(); for (const x of nums) cnt.set(x, (cnt.get(x) || 0) + 1);
  const vals = [...cnt.keys()].sort((x, y) => x - y), res = [];
  for (let i = 0; i < vals.length; i++) for (let j = i; j < vals.length; j++) {
    const a = vals[i], b = vals[j], c = -a - b;
    if (c < b) continue;
    const need = new Map(); for (const v of [a, b, c]) need.set(v, (need.get(v) || 0) + 1);
    let ok = true; for (const [v, k] of need) if ((cnt.get(v) || 0) < k) ok = false;
    if (ok) res.push([a, b, c]);
  }
  return res;
}
